public class DebuggerBlockChooserDialog : ReusableDialogComponentProvider {
	public static class MemoryBlockRow {
		private Program program;
		private MemoryBlock block;
		private double score;

		protected MemoryBlockRow(Program program, MemoryBlock block) {
			this.program = program;
			this.block = block;
		}

		public Program getProgram() {
			return program;
		}

		public MemoryBlock getBlock() {
			return block;
		}

		public string getProgramName() {
			return program.getName();
		}

		public string getBlockName() {
			return block.getName();
		}

		public Address getMinAddress() {
			return block.getStart();
		}

		public Address getMaxAddress() {
			return block.getEnd();
		}

		public long getLength() {
			return block.getSize();
		}

		public double getScore() {
			return score;
		}

		public double score(TraceSection section, long snap, DebuggerStaticMappingService service) {
			if (section == null) {
				return score = 0;
			}
			return score = service.proposeSectionMap(section, snap, program, block).computeScore();
		}

		public double score(TraceMemoryRegion region, long snap,
				DebuggerStaticMappingService service) {
			if (region == null) {
				return score = 0;
			}
			return score = service.proposeRegionMap(region, snap, program, block).computeScore();
		}

		public ProgramLocation getProgramLocation() {
			return new ProgramLocation(program, block.getStart());
		}
	}

	class MemoryBlockTableColumns : EnumeratedTableColumn<MemoryBlockTableColumns, MemoryBlockRow>
{	public static readonly MemoryBlockTableColumns SCORE = new(, typeof(Double), MemoryBlockRow.getScore, SortDirection.DESCENDING);
	public static readonly MemoryBlockTableColumns PROGRAM = new(, typeof(string), MemoryBlockRow.getProgramName, SortDirection.ASCENDING);
	public static readonly MemoryBlockTableColumns BLOCK = new(, typeof(string), MemoryBlockRow.getBlockName, SortDirection.ASCENDING);
